var f = document.querySelector('form');
f.addEventListener('submit', function (e) {
  e.preventDefault();
  var data = new FormData(f), lines = [];
  data.forEach(function (v, k) { lines.push(k + ' = ' + (v && v.name !== undefined ? v.name : v)); });
  document.getElementById('out').textContent = lines.join('\n') || '(nothing)';
});

