examples.css:
body{font-family:sans-serif;max-width:480px}
form div{margin:10px 0}
label{display:block;font-weight:bold;margin-bottom:3px}
input:not([type=checkbox]):not([type=radio]):not([type=range]):not([type=color]),select,textarea{padding:6px;width:100%;box-sizing:border-box}
button,input[type=submit]{padding:8px 14px;cursor:pointer}
pre{background:#f4f4f4;padding:8px;border-radius:6px;white-space:pre-wrap}
input:user-invalid{border:2px solid crimson}
input:valid{border-color:seagreen}

